{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_loss",
      "evidence": [
        {"kind": "trace", "sql": "SELECT count(*) AS timed_out_calls, round(avg(duration)/1e6,0) AS avg_ms FROM abnormal_traces c WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND c.duration > 100000000000 AND NOT EXISTS (SELECT 1 FROM abnormal_traces k WHERE k.parent_span_id=c.span_id AND k.attr_span_kind='Server')", "claim": "Seven seat client calls with no callee span run about 130 s and end in error, i.e. they never get a response."},
        {"kind": "metric", "sql": "SELECT 'ab' src, metric, attr_source, attr_destination, round(avg(value),1) avg_v FROM abnormal_metrics_sum WHERE metric IN ('hubble_flows_processed_total','hubble_tcp_flags_total') AND attr_source LIKE '%seat-service%' AND attr_destination LIKE '%order-other%' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', metric, attr_source, attr_destination, round(avg(value),1) FROM normal_metrics_sum WHERE metric IN ('hubble_flows_processed_total','hubble_tcp_flags_total') AND attr_source LIKE '%seat-service%' AND attr_destination LIKE '%order-other%' GROUP BY 1,2,3,4", "claim": "Seat-to-order-other connection flow and TCP flag counts rise sharply in the abnormal period (retransmits), versus normal."},
        {"kind": "log", "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-seat-service' AND message ILIKE '%Connection timed out%' GROUP BY 1,2", "claim": "Seat logs SEVERE I/O errors: POST to ts-order-other-service timed out with connection timeout."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel2-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, k.service_name callee, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) p50_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces k ON k.parent_span_id=c.span_id AND k.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel2-service' AND k.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel2 calls to seat take a median of ~13 s, with 6 of 23 calls in error."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, k.service_name callee, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces k ON k.parent_span_id=c.span_id AND k.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND k.service_name='ts-travel2-service' GROUP BY 1,2", "claim": "Route-plan calls to travel2 reach p95 ~156 s, with 4 of 20 calls in error."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
